// ── Anonymising live data fetcher ─────────────────────────────────────────────
// CTI work needs OPSEC: ransomware groups, leak-site operators and stealer-log
// forums log every visitor. Your corporate IP appearing in their access logs is
// itself intelligence ("which company is watching us?"). This module ensures
// the laptop NEVER opens a TCP connection to those hosts. All upstream fetches
// originate from the Supabase edge function (`/functions/v1/proxy`), which:
//
//   • strips every identifying client header (UA, Referer, cookies, fingerprint)
//   • injects a neutral, rotating User-Agent
//   • optionally egresses through Tor / residential / VPN if EGRESS_PROXY_URL
//     is configured on the function
//   • lives behind Supabase's shared AWS IP space — not your office ASN
//
// The browser only ever talks to two hosts: your Vercel/host domain and your
// Supabase project URL. Threat-intel sources see only Supabase egress.

import { getRuntimeConfig } from "./runtime-config";

const TIMEOUT_MS = 20_000;

// Hosts the Supabase proxy is allowed to fetch (kept in sync with proxy/index.ts).
// All hosts handled by this module are routed via Supabase. No public CORS
// proxies — those services log every URL you query and are themselves a leak.
const SUPABASE_PROXY_OK =
  /(?:cisa\.gov|nvd\.nist\.gov|abuse\.ch|ransomware\.live|ransomlook\.io|shodan\.io|greynoise\.io|alienvault\.com|first\.org|osv\.dev|haveibeenpwned\.com|abuseipdb\.com|rdap\.org|ip-api\.com|isc\.sans\.edu|crt\.sh|urlscan\.io|pulsedive\.com|circl\.lu|vulners\.com|github(?:usercontent)?\.com|news\.google\.com|feedburner\.com|bleepingcomputer\.com|krebsonsecurity\.com|therecord\.media|darkreading\.com|securityweek\.com|thehackernews\.com|theregister\.com|schneier\.com|cyberscoop\.com|scmagazine\.com|infosecurity-magazine\.com|talosintelligence\.com|blogspot\.com|microsoft\.com|openphish\.com|xposedornot\.com|leakcheck\.io|cloudflare-dns\.com|dns\.google)$/i;

interface LiveFetchOpts extends RequestInit {
  /** Override timeout (default 20s) */
  timeoutMs?: number;
  /** Parse as JSON (default true) — set false for RSS/XML/text */
  json?: boolean;
}

/**
 * Fetch a remote URL while keeping the laptop anonymous.
 * Always relays through the Supabase edge function — the threat source never
 * sees the client's IP, headers, or fingerprint.
 */
export async function liveFetch<T = any>(url: string, opts: LiveFetchOpts = {}): Promise<T | null> {
  const { timeoutMs = TIMEOUT_MS, json = true, ...init } = opts;

  let host: string;
  try { host = new URL(url).hostname; } catch { return null; }
  if (!SUPABASE_PROXY_OK.test(host)) {
    // Host not in allowlist — refuse rather than fall back to a direct fetch
    // that would expose the laptop. Add the host to both allowlists if needed.
    if (typeof console !== "undefined") {
      console.warn("[live-fetch] host not in allowlist, blocked for OPSEC:", host);
    }
    return null;
  }

  const cfg = getRuntimeConfig();
  const proxyBase = cfg.corsProxyUrl
    ? `${cfg.corsProxyUrl.replace(/\/$/, "")}?url=`
    : `${cfg.supabaseUrl}/functions/v1/proxy?url=`;
  const proxyUrl = `${proxyBase}${encodeURIComponent(url)}`;

  const proxyInit: RequestInit = {
    method: init.method ?? "GET",
    headers: {
      ...(cfg.corsProxyUrl
        ? {}
        : {
            apikey: cfg.supabasePublishableKey,
            Authorization: `Bearer ${cfg.supabasePublishableKey}`,
          }),
      ...(init.body ? { "Content-Type": "application/json" } : {}),
    },
    body: init.body,
    // Don't send cookies/credentials — Supabase auth is via apikey header.
    credentials: "omit",
    cache: "no-store",
    referrerPolicy: "no-referrer",
  };

  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const r = await fetch(proxyUrl, { ...proxyInit, signal: ctrl.signal });
    clearTimeout(t);
    if (!r.ok) return null;
    if (json) {
      try { return await r.json(); } catch { return null; }
    }
    return (await r.text()) as any;
  } catch {
    clearTimeout(t);
    return null;
  }
}

export async function liveFetchJSON<T = any>(url: string): Promise<T | null> {
  return liveFetch<T>(url);
}

export async function liveFetchPOST<T = any>(url: string, body: any): Promise<T | null> {
  return liveFetch<T>(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: typeof body === "string" ? body : JSON.stringify(body),
  });
}
